-- Development-only idempotent bulk mock data for thread layout testing.
-- Creates 200 threads and 2-6 posts per thread (800 posts total).
WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<200)
INSERT OR IGNORE INTO threads(id,board_id,created_by_profile_id,title,language,region,pinned,created_at,updated_at,thread_type,tags_json,status,moderation_status)
SELECT printf('mock-thread-%03d',n),
  'board-cat03-board02',
  CASE (n%4) WHEN 0 THEN 'profile-me' WHEN 1 THEN 'profile-noa' WHEN 2 THEN 'profile-rin' ELSE 'profile-yoru' END,
  (CASE ((n-1)%20) WHEN 0 THEN CAST(X'E69C80E8BF91E4BDBFE381A3E381A6E38288E3818BE381A3E3819FE98193E585B7E38292E69599E38188E381A6E3818FE381A0E38195E38184' AS TEXT) WHEN 1 THEN CAST(X'E5889DE5BF83E88085E3818CE69C80E5889DE381ABE8A69AE38188E3828BE381B9E3818DE38193E381A8E381AFE4BD95E381A7E38199E3818B' AS TEXT) WHEN 2 THEN CAST(X'E38193E381AEE3838BE383A5E383BCE382B9E38292E381A9E38186E8AAADE381BFE8A7A3E38191E381B0E38288E38184E381A7E38199E3818B' AS TEXT) WHEN 3 THEN CAST(X'E6AF8EE697A5E7B69AE38191E38284E38199E38184E7BF92E685A3E38292E585B1E69C89E38197E38288E38186' AS TEXT) WHEN 4 THEN CAST(X'E5A4B1E69597E3818BE38289E5ADA6E38293E381A0E38193E381A8E38292E8A898E98CB2E38199E3828BE382B9E383ACE38383E38389' AS TEXT) WHEN 5 THEN CAST(X'E3818AE38199E38199E38281E381AEE4BD9CE59381E381A8E8A68BE381A9E38193E3828DE38292E8AA9EE3828DE38186' AS TEXT) WHEN 6 THEN CAST(X'E4B896E7958CE59084E59CB0E381AEE69AAEE38289E38197E381AEE98195E38184E381ABE381A4E38184E381A6' AS TEXT) WHEN 7 THEN CAST(X'E4BB95E4BA8BE38292E58AB9E78E87E58C96E38199E3828BE5B08FE38195E381AAE5B7A5E5A4AB' AS TEXT) WHEN 8 THEN CAST(X'E4BB8AE980B1E3828FE3818BE38289E381AAE3818BE381A3E3819FE38193E381A8E38292E8B3AAE5958FE38199E3828BE5A0B4E68980' AS TEXT) WHEN 9 THEN CAST(X'E8B2B7E381A3E381A6E5BE8CE68294E38197E381AAE3818BE381A3E3819FE38282E381AE' AS TEXT) WHEN 10 THEN CAST(X'E59CB0E59F9FE381A7E3818AE38199E38199E38281E381AEE5A0B4E68980E38292E7B4B9E4BB8BE38197E38288E38186' AS TEXT) WHEN 11 THEN CAST(X'E38397E383ADE382B0E383A9E3839FE383B3E382B0E381AEE79691E5958FE38292E8A7A3E6B1BAE38199E3828BE382B9E383ACE38383E38389' AS TEXT) WHEN 12 THEN CAST(X'E581A5E5BAB7E79A84E381AAE7949FE6B4BBE381AEE3819FE38281E381ABE7B69AE38191E381A6E38184E3828BE38193E381A8' AS TEXT) WHEN 13 THEN CAST(X'E69699E79086E38292E7B0A1E58D98E381ABE38199E3828BE6AEB5E58F96E3828AE381A8E5B7A5E5A4AB' AS TEXT) WHEN 14 THEN CAST(X'E382B9E3839DE383BCE38384E8A6B3E688A6E381AEE6B3A8E79BAEE3839DE382A4E383B3E38388' AS TEXT) WHEN 15 THEN CAST(X'E382B2E383BCE383A0E381AEE694BBE795A5E68385E5A0B1E381A8E5889DE5BF83E88085E59091E38191E58AA9E8A880' AS TEXT) WHEN 16 THEN CAST(X'E5ADA6E7BF92E38292E995B7E3818FE7B69AE38191E3828BE3819FE38281E381AEE696B9E6B395' AS TEXT) WHEN 17 THEN CAST(X'E69785E8A18CE5898DE381ABE7A2BAE8AA8DE38197E381A6E3818AE3818DE3819FE38184E38193E381A8' AS TEXT) WHEN 18 THEN CAST(X'E69687E58C96E38284E8A880E8AA9EE381AEE98195E38184E381A7E9A99AE38184E3819FE38193E381A8' AS TEXT) WHEN 19 THEN CAST(X'E7B58CE6B888E381AEE59FBAE69CACE38292E3828FE3818BE3828AE38284E38199E3818FE69599E38188E381A6E3818FE381A0E38195E38184' AS TEXT) END) || printf(' #%03d',n),
  CASE (n%5) WHEN 0 THEN 'en' ELSE 'ja' END,
  CASE (n%6) WHEN 0 THEN 'north-america' WHEN 1 THEN 'local' WHEN 2 THEN 'europe' WHEN 3 THEN 'asia-pacific' WHEN 4 THEN 'africa' ELSE 'global' END,
  0,
  datetime('2026-07-01 00:00:00',printf('+%d minutes',n*37)),
  datetime('2026-07-23 12:00:00',printf('-%d minutes',n*19)),
  CASE (n%4) WHEN 0 THEN 'question' WHEN 1 THEN 'information' WHEN 2 THEN 'recruitment' ELSE 'chat' END,
  CASE (n%4)
    WHEN 0 THEN CAST(X'5B22E8B3AAE5958F222C22E5889DE5BF83E88085225D' AS TEXT)
    WHEN 1 THEN CAST(X'5B22E68385E5A0B1E585B1E69C89225D' AS TEXT)
    WHEN 2 THEN CAST(X'5B22E58B9FE99B86222C22E4BAA4E6B581225D' AS TEXT)
    ELSE CAST(X'5B22E99B91E8AB87225D' AS TEXT)
  END,
  'open','active'
FROM seq;

WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<200)
INSERT OR IGNORE INTO thread_posts(id,thread_id,post_no,author_profile_id,display_name,body,reply_to_post_id,created_at,is_anonymous)
SELECT printf('mock-post-%03d-01',n),printf('mock-thread-%03d',n),1,
  CASE (n%4) WHEN 0 THEN 'profile-me' WHEN 1 THEN 'profile-noa' WHEN 2 THEN 'profile-rin' ELSE 'profile-yoru' END,
  CASE (n%4) WHEN 0 THEN 'J Kamma' WHEN 1 THEN 'Noa' WHEN 2 THEN 'Rin' ELSE 'Yoru' END,
  CASE ((n-1)%6) WHEN 0 THEN CAST(X'' AS TEXT) WHEN 1 THEN CAST(X'' AS TEXT) WHEN 2 THEN CAST(X'E5908CE38198E38386E383BCE3839EE381A7E38282E792B0E5A283E381ABE38288E381A3E381A6E7AD94E38188E3818CE5A489E3828FE3828BE381A8E6809DE38184E381BEE38199E38082E69DA1E4BBB6E38292E6988EE7A2BAE381ABE38197E381AAE3818CE38289E68385E5A0B1E4BAA4E68F9BE38197E381BEE38197E38287E38186E38082' AS TEXT) WHEN 3 THEN CAST(X'E4B880E6ACA1E68385E5A0B1E38284E58F82E88083E8B387E69699E3818CE38182E3828BE5A0B4E59088E381AFE587BAE585B8E38282E6B7BBE38188E381A6E3818FE381A0E38195E38184E38082E58FA4E3818FE381AAE381A3E3819FE68385E5A0B1E381AFE8A882E6ADA3E383ACE382B9E381A7E69BB4E696B0E381A7E3818DE381BEE38199E38082' AS TEXT) WHEN 4 THEN CAST(X'' AS TEXT) WHEN 5 THEN CAST(X'E5889DE5BF83E88085E381ABE38282E79086E8A7A3E381A7E3818DE3828BE8AAACE6988EE38292E99B86E38281E3819FE38184E381A7E38199E38082E5B082E99680E794A8E8AA9EE38292E4BDBFE38186E5A0B4E59088E381AFE79FADE38184E8A39CE8B6B3E3818CE38182E3828BE381A8E58AA9E3818BE3828AE381BEE38199E38082' AS TEXT) END,
  NULL,datetime('2026-07-01 00:00:00',printf('+%d minutes',n*37)),0
FROM seq;

WITH RECURSIVE threads_seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM threads_seq WHERE n<200),
reply_seq(r) AS (SELECT 2 UNION ALL SELECT r+1 FROM reply_seq WHERE r<6)
INSERT OR IGNORE INTO thread_posts(id,thread_id,post_no,author_profile_id,display_name,body,reply_to_post_id,created_at,is_anonymous)
SELECT printf('mock-post-%03d-%02d',n,r),printf('mock-thread-%03d',n),r,
  CASE ((n+r)%5) WHEN 0 THEN NULL WHEN 1 THEN 'profile-noa' WHEN 2 THEN 'profile-rin' WHEN 3 THEN 'profile-yoru' ELSE 'profile-me' END,
  CASE ((n+r)%5) WHEN 0 THEN CAST(X'E58CBFE5908D' AS TEXT) || printf(' %d',r) WHEN 1 THEN 'Noa' WHEN 2 THEN 'Rin' WHEN 3 THEN 'Yoru' ELSE 'J Kamma' END,
  CASE r WHEN 2 THEN CAST(X'' AS TEXT) WHEN 3 THEN CAST(X'' AS TEXT) WHEN 4 THEN CAST(X'E58F82E88083E381ABE381AAE3828BE68385E5A0B1E381A7E38199E38082E58FAFE883BDE381AAE38289E8B2BBE794A8E38081E68980E8A681E69982E99693E38081E6B3A8E6848FE782B9E38282E8BFBDE8A898E38199E3828BE381A8E38081E6AF94E8BC83E38197E38284E38199E3818FE381AAE3828BE381A8E6809DE38184E381BEE38199E38082' AS TEXT) WHEN 5 THEN CAST(X'E8A39CE8B6B3E38197E381BEE38199E38082E4BBA5E5898DE381AFE5908CE38198E8AA8DE8AD98E381A7E38197E3819FE3818CE38081E78FBEE59CA8E381AFE4BB95E6A798E3818CE5A489E3828FE381A3E381A6E38184E381BEE38199E38082E69C80E696B0E381AEE585ACE5BC8FE68385E5A0B1E38282E7A2BAE8AA8DE38197E381A6E3818FE381A0E38195E38184E38082' AS TEXT) WHEN 6 THEN CAST(X'E8B3AAE5958FE381A7E38199E38082E5889DE5BF83E88085E3818CE4B880E381A4E381A0E38191E8A9A6E38199E381AAE38289E38081E381A9E381AEE696B9E6B395E3818BE38289E5A78BE38281E3828BE381AEE3818CE5AE89E585A8E381A7E38197E38287E38186E3818BE38082' AS TEXT) WHEN 7 THEN CAST(X'' AS TEXT) END,
  CASE WHEN r IN (4,6) THEN printf('mock-post-%03d-%02d',n,r-2) ELSE printf('mock-post-%03d-01',n) END,
  datetime('2026-07-01 00:00:00',printf('+%d minutes',n*37+r*11)),
  CASE WHEN ((n+r)%5)=0 THEN 1 ELSE 0 END
FROM threads_seq CROSS JOIN reply_seq WHERE r<=2+(n%5);

UPDATE threads
SET best_answer_post_id=replace(id,'mock-thread-','mock-post-') || '-02',
    solved_at='2026-07-23T12:00:00.000Z',
    status='closed'
WHERE id LIKE 'mock-thread-%' AND thread_type='question';

WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n<200)
INSERT OR IGNORE INTO thread_post_quality_votes(post_id,profile_id,dimension,value,created_at,updated_at)
SELECT printf('mock-post-%03d-02',n),
  CASE (n%4) WHEN 0 THEN 'profile-noa' WHEN 1 THEN 'profile-rin' WHEN 2 THEN 'profile-yoru' ELSE 'profile-me' END,
  'helpful',1,'2026-07-23T12:00:00.000Z','2026-07-23T12:00:00.000Z'
FROM seq;

WITH RECURSIVE seq(n) AS (SELECT 10 UNION ALL SELECT n+10 FROM seq WHERE n<200)
INSERT OR IGNORE INTO thread_summary_revisions(id,thread_id,revision_no,body,source,status,created_by_profile_id,reviewed_by_profile_id,created_at,reviewed_at)
SELECT printf('mock-summary-%03d',n),printf('mock-thread-%03d',n),1,
  CAST(X'' AS TEXT),
  'community','published','profile-noa','profile-yoru','2026-07-23T12:00:00.000Z','2026-07-23T12:05:00.000Z'
FROM seq;
